<?php
/** OpenAI image provider adapter structure. @package AIContentStudio */
if ( ! defined( 'ABSPATH' ) ) { exit; }

final class AICS_OpenAI_Image_Provider implements AICS_Image_Provider_Interface {
	public const PROVIDER_KEY='openai'; public const DEFAULT_MODEL='gpt-image-2'; private const MODELS=array('gpt-image-2'); private const ENDPOINT='https://api.openai.com/v1/images/generations'; private const TIMEOUT=180; private const MAX_ENCODED_BYTES=34952536;
	private const SIZE_MAP=array('square'=>'1024x1024','landscape'=>'1536x1024','portrait'=>'1024x1536'); private const QUALITY_MAP=array('standard'=>'medium','high'=>'high'); private const MIME_MAP=array('png'=>'image/png','jpeg'=>'image/jpeg','webp'=>'image/webp');
	private AICS_HTTP_Client $http_client;
	public function __construct(?AICS_HTTP_Client $http_client=null){$this->http_client=$http_client??new AICS_HTTP_Client();}
	public function get_provider_key():string{return self::PROVIDER_KEY;} public function get_display_name():string{return 'OpenAI';}
	public function is_configured():bool{return AICS_Settings::has_openai_api_key();}
	public function validate_configuration():array{$settings=AICS_Featured_Image_Settings::get_effective();if(!$this->is_configured()){return $this->validation(false,'image_provider_credentials_missing',__('Provider credentials are missing.','ai-content-studio'));}if(self::PROVIDER_KEY!==$settings['provider']||!in_array($settings['model'],self::MODELS,true)){return $this->validation(false,'image_provider_model_invalid',__('The selected image model is not configured.','ai-content-studio'));}return $this->validation(true,'image_provider_configured',__('Ready for image generation.','ai-content-studio'));}
	public function get_capabilities():array{return array('supported_models'=>self::MODELS,'default_model'=>self::DEFAULT_MODEL,'supported_aspect_ratios'=>array('landscape','square','portrait'),'supported_quality_levels'=>array('standard','high'),'supported_output_formats'=>array('png','jpeg','webp'),'supports_prompt_revision'=>true,'supports_base64_output'=>true,'supports_url_output'=>false);}
	public function generate(AICS_Image_Generation_Request $request):AICS_Image_Generation_Result{$api_key=AICS_Settings::get('openai_api_key','');if(!is_string($api_key)||''===$api_key){return $this->failure('image_provider_not_configured',__('The image provider credentials are not configured.'),false,0,$request);}$cap=$this->get_capabilities();if(self::PROVIDER_KEY!==$request->get_provider()||!in_array($request->get_model(),$cap['supported_models'],true)||!isset(self::SIZE_MAP[$request->get_aspect_ratio()],self::QUALITY_MAP[$request->get_quality()],self::MIME_MAP[$request->get_output_format()])){return $this->failure('image_generation_not_supported',__('The requested image configuration is not supported.','ai-content-studio'),false,0,$request);}$response=$this->http_client->post_json(self::ENDPOINT,array('Authorization'=>'Bearer '.$api_key,'Content-Type'=>'application/json'),array('model'=>$request->get_model(),'prompt'=>$request->get_prompt(),'size'=>self::SIZE_MAP[$request->get_aspect_ratio()],'quality'=>self::QUALITY_MAP[$request->get_quality()],'output_format'=>$request->get_output_format(),'n'=>1),self::TIMEOUT);unset($api_key);if(!$response['success']){return $this->map_failure($response,$request);}$encoded=$response['data']['data'][0]['b64_json']??null;if(!is_string($encoded)||''===$encoded||strlen($encoded)>self::MAX_ENCODED_BYTES){return $this->failure(is_string($encoded)&&strlen($encoded)>self::MAX_ENCODED_BYTES?'image_file_too_large':'invalid_image_response',__('The image provider returned an invalid image response.','ai-content-studio'),false,$response['status_code'],$request);}$bytes=base64_decode($encoded,true);unset($encoded,$response['data']);if(false===$bytes){return $this->failure('image_base64_decode_failed',__('The generated image data could not be decoded.','ai-content-studio'),false,$response['status_code'],$request);}if(''===$bytes){return $this->failure('invalid_image_response',__('The image provider returned an empty image.','ai-content-studio'),false,$response['status_code'],$request);}if(strlen($bytes)>AICS_Temporary_Image_File::MAX_BYTES){unset($bytes);return $this->failure('image_file_too_large',__('The generated image exceeded the maximum file size.','ai-content-studio'),false,$response['status_code'],$request);}$temporary=AICS_Temporary_Image_File::create_from_bytes($bytes,$request->get_output_format());unset($bytes);if(is_wp_error($temporary)){return $this->failure($temporary->get_error_code(),$temporary->get_error_message(),false,$response['status_code'],$request);}$result=AICS_Image_Generation_Result::success(array('provider'=>self::PROVIDER_KEY,'model'=>$request->get_model(),'output_type'=>$request->get_output_format(),'mime_type'=>$temporary->get_mime_type(),'width'=>$temporary->get_width(),'height'=>$temporary->get_height(),'file_size'=>$temporary->get_file_size(),'temporary_file'=>$temporary,'message'=>__('Image generation succeeded.','ai-content-studio'),'http_status'=>$response['status_code']));if(is_wp_error($result)){$temporary->cleanup();return $this->failure('image_file_validation_failed',__('The generated image result could not be prepared.','ai-content-studio'),false,$response['status_code'],$request);}return $result;}
	private function map_failure(array $response,AICS_Image_Generation_Request $request):AICS_Image_Generation_Result{$status=absint($response['status_code']??0);if(401===$status){return $this->failure('image_provider_authentication_failed',__('The image provider rejected the configured credentials.','ai-content-studio'),false,$status,$request);}if(403===$status){return $this->failure('image_provider_permission_denied',__('The configured account does not currently allow image generation.','ai-content-studio'),false,$status,$request);}if(429===$status){return $this->failure('image_provider_rate_limited',__('The image provider rate limit was reached.','ai-content-studio'),true,$status,$request);}if('timeout'===($response['error_code']??'')){return $this->failure('image_provider_timeout',__('The image provider request timed out.','ai-content-studio'),true,$status,$request);}return $this->failure('image_provider_request_failed',__('The image provider request failed.','ai-content-studio'),0===$status||$status>=500,$status,$request);}
	private function failure(string $code,string $message,bool $retryable,int $status,AICS_Image_Generation_Request $request):AICS_Image_Generation_Result{return AICS_Image_Generation_Result::failure($code,$message,self::PROVIDER_KEY,$retryable,$status,$request->get_model());}
	private function validation(bool $success,string $code,string $message):array{return array('success'=>$success,'code'=>$code,'message'=>$message);}
}
